    { 'key': 'customer', 'label': 'Customer', 'badge': String(conversation.value.length || ''), 'tone': 'default' },
    { 'key': 'operator', 'label': 'Operator', 'badge': operatorBadge, 'tone': operatorTone },
  ];
});

const rightTabs = computed<readonly PaneTab[]>(() => {
  const traceCount = trace.value.length + logEvents.value.length;
  return [
    { 'key': 'dag', 'label': 'DAG', 'badge': isRunning.value ? 'live' : '', 'tone': isRunning.value ? 'live' : 'default' },
    { 'key': 'config', 'label': 'Config', 'badge': humanMode.value ? 'HUMAN' : '', 'tone': humanMode.value ? 'warn' : 'default' },
    {
      'key': 'llm',
      'label': 'LLM Select',
      'badge': llmWarning.value === null ? activeBackend.value ?? '' : '⚠',
      'tone': llmWarning.value === null ? 'default' : 'warn',
    },
    { 'key': 'trace', 'label': 'Trace', 'badge': String(traceCount || ''), 'tone': isRunning.value ? 'live' : 'default' },
  ];
});

async function selectBackend(id: string): Promise<void> {
  const resolved = await browserRuntime.resolveProviderId(id);
  if (resolved !== null) {
    activeBackend.value = resolved;
  }
}

function selectPreferredModels(models: Partial<Record<ProviderId, string>>): void {
  preferredModels.value = models;
}

async function refreshBackends(): Promise<void> {
  const refreshed = await browserRuntime.refreshBackends({
    'apiKeys': apiKeys.value,
    'isMobile': isMobile.value,
    'preferredModels': preferredModels.value,
  });
  backends.value = refreshed.backends;
  noModel.value = refreshed.noModel;
}

watch(
  () => conversation.value.length,
  async () => {
    const element = streamRef.value;
    if (element === null) {
      return;
    }
    const wasAtBottom = (element.scrollHeight - element.scrollTop - element.clientHeight) < 80;
    await nextTick();
    if (wasAtBottom) {
      element.scrollTo({ 'top': element.scrollHeight, 'behavior': 'smooth' });
    }
  },
);

watch(apiKeys, async () => {
  await browserRuntime.saveApiKeys(apiKeys.value);
  await refreshBackends();
}, { 'deep': true });

watch(preferredModels, async (models) => {
  await browserRuntime.savePreferredModels(models);
  await refreshBackends();
}, { 'deep': true });

watch(activeBackend, (id) => {
  void browserRuntime.saveActiveBackend(id);
});

onMounted(async () => {
  const bootstrap = await browserRuntime.loadBootstrapState();

  isMobile.value = bootstrap.isMobile;
  apiKeys.value = bootstrap.apiKeys;
  preferredModels.value = bootstrap.preferredModels;
  backends.value = bootstrap.backends;
  noModel.value = bootstrap.noModel;
  activeBackend.value = bootstrap.activeBackend;

  if (bootstrap.backendNote !== null) {
    logger.note(bootstrap.backendNote);
  }
  if (bootstrap.noModel) {
    logger.warn('no LLM backend detected; select one to enable the workflow');
    return;
  }
});

async function buildServices(): Promise<DispatcherServices> {
  return browserRuntime.buildServices({
    'activeBackend': activeBackend.value,
    'apiKeys': apiKeys.value,
    'baseUrl': import.meta.env.BASE_URL,
    'language': visitorLanguage,
    'model': resolvedModel.value,
  });
}

async function ask(): Promise<void> {
  const submittedQuery = customerQuery.value.trim();
  if (isRunning.value || submittedQuery.length === 0 || activeBackend.value === null) {
    return;
  }

  const setup = DispatcherRunnerSetup.forDispatch(currentRunnerState(), submittedQuery, Date.now());
  applyRunnerState(setup.initialState);

  let services: DispatcherServices;
  try {
    services = await buildServices();
  } catch (error) {
    applyRunnerState(setup.rollbackState());
    reportRunnerFault(
      'dispatch-setup',
      'dispatch setup failed: ',
      error instanceof Error ? error : new Error(String(error)),
    );
    return;
  }

  logger.clear();
  logger.note(`run start — message: "${submittedQuery}" · humanMode: ${String(humanMode.value)}`);
  await dagGraph.value?.reset();

  const state = new DispatcherState();
  state.message = submittedQuery;
  state.humanMode = humanMode.value;
  state.classificationMode = classificationMode.value;
  state.language = visitorLanguage;

  const dispatcher = createDispatcher(services);
  const item = { 'id': state.runIri, state };

  activeAbortController = new AbortController();
  try {
    await DispatcherBatchDispatch.run(dispatcher, dispatcherDagName, [item], {
      'signal': activeAbortController.signal,
    });
  } catch (error) {
    reportRunnerFault('execute', 'execute error: ', error instanceof Error ? error : new Error(String(error)));
  } finally {
    if (services.intent.displayName !== null && embedderDisplayName.value !== services.intent.displayName) {
      embedderDisplayName.value = services.intent.displayName;
      logger.note(`embedder provisioned: ${services.intent.displayName}`);
    }
    await dispatcher.destroy();
    activeAbortController = null;
    isRunning.value = false;
  }
}

async function sendOperatorResponse(): Promise<void> {
  const parkedRun = parkedExecution;
  const responseText = operatorInput.value.trim();
  if (parkedRun === null || responseText.length === 0) {
    return;
  }

  const setup = DispatcherRunnerSetup.forResume(currentRunnerState(), {
    'node': 'operator',
    'ts': Date.now(),
    'variant': 'start',
  });
  applyRunnerState(setup.initialState);

  let services: DispatcherServices;
  try {
    services = await buildServices();
  } catch (error) {
    applyRunnerState(setup.rollbackState());
    reportRunnerFault(
      'resume-setup',
      'resume setup failed: ',
      error instanceof Error ? error : new Error(String(error)),
    );
    return;
  }

  let restored: { readonly dagName: string; readonly cursor: string; readonly state: DispatcherState };
  try {
    const checkpoint = await Checkpoint.capture(parkedRun.dagName, parkedRun.result);
    restored = await checkpoint.restoreState(
      CheckpointRestoreAdapter.wrap(() => new DispatcherState()),
    );
  } catch (error) {
    applyRunnerState(setup.rollbackState());
    reportRunnerFault(
      'checkpoint-restore',
      'checkpoint restore failed: ',
      error instanceof Error ? error : new Error(String(error)),
    );
    return;
  }

  restored.state.response = responseText;
  logger.note(`operator response captured — resuming from cursor: ${parkedRun.cursor}`);
  await dagGraph.value?.reset();

  const dispatcher = createDispatcher(services);
  const item = { 'id': restored.state.runIri, 'state': restored.state };

  activeAbortController = new AbortController();
  try {
    const resumed = await DispatcherBatchDispatch.resume(
      dispatcher,
      restored.dagName,
      item,
      restored.cursor,
      { 'signal': activeAbortController.signal },
    );
    if (resumed.awaitingInput.length === 0) {
      leftActiveKey.value = 'customer';
    }
  } catch (error) {
    reportRunnerFault('resume', 'resume error: ', error instanceof Error ? error : new Error(String(error)));
  } finally {
    await dispatcher.destroy();
    activeAbortController = null;
    isRunning.value = false;
  }
}

function reset(): void {
  conversation.value = [];
  trace.value = [];
  parkedExecution = null;
  parked.value = null;
  escalationReason.value = '';
  terminalVariant.value = 'pending';
  customerQuery.value = '';
  operatorInput.value = '';
  leftActiveKey.value = 'customer';
  logger.clear();
  void dagGraph.value?.reset();
}

const lifecycleBadge = computed<string>(() => {
  if (isRunning.value) {
    return 'running';
  }
  if (parked.value !== null) {
    return 'awaiting-input';
  }
  return terminalVariant.value === 'pending' ? 'idle' : terminalVariant.value;
});

const isAwaiting = computed(() => parked.value !== null);

const EXAMPLE_PROMPTS: readonly string[] = [
  'What are your store hours?',
  'Do you carry graphic novels?',
  'I need a refund for my last order',
  'My account was charged twice',
];

function fillPrompt(text: string): void {
  customerQuery.value = text;
}
</script>

<template>
  <div :class="['dispatcher-runner', { 'is-running': isRunning, 'is-awaiting': isAwaiting }]">

    <!-- No-model gate: shown when no real backend is available on this device. -->
    <section v-if="noModel" class="dr-no-model-gate" role="alert">
      <h3>No LLM backend detected</h3>
      <p>The Dispatcher workflow uses real LLM calls for classification and reply composition. Enable one of the backends below to start:</p>
      <LlmConfigurationPane
        :backends="backends"
        :active-id="activeBackend"
        :api-keys="apiKeys"
        :preferred-models="preferredModels"
        :is-mobile="isMobile"
        @update:active-id="selectBackend"
        @update:api-keys="apiKeys = $event"
        @update:preferred-models="selectPreferredModels"
      />
    </section>

    <template v-else>
    <RunnableExampleWorkbench
      left-label="Customer"
      right-label="Operator / Graph"
      :right-hint="isAwaiting ? 'awaiting operator' : isRunning ? 'running…' : 'ready'"
      secondary-width="1.35fr"
    >
      <template #left-meta>
        <span :class="['dr-badge', `dr-badge--${lifecycleBadge}`]">{{ lifecycleBadge }}</span>
      </template>

      <!-- LEFT: Stream | Config -->
      <template #left>
        <PanesTabs :tabs="leftTabs" :default-key="leftActiveKey" class="dr-tabs">

          <!-- Customer tab: conversation history -->
          <template #customer>
            <div class="dr-stream-pane">
              <ol v-if="conversation.length > 0" ref="streamRef" class="dr-conversation">
                <li
                  v-for="turn in conversation"
                  :key="turn.ts"
                  :class="['dr-turn', `dr-turn--${turn.role}`]"
                >
                  <span class="dr-turn-role">
                    {{ turn.role === 'customer' ? 'Customer' : turn.role === 'agent' ? 'Agent (AI)' : 'Operator' }}
                  </span>
                  <p class="dr-turn-text">{{ turn.text }}</p>
                </li>
              </ol>
              <p v-else class="dr-empty">
                Type a customer message below and click Send.
              </p>

              <div class="dr-send-area">
                <textarea
                  v-model="customerQuery"
                  :disabled="isRunning || isAwaiting"
                  class="dr-textarea"
                  rows="2"
                  placeholder="Customer message…"
                  @keydown.enter.prevent="!isRunning && !isAwaiting && ask()"
                />
                <div class="dr-send-row">
                  <button
                    type="button"
                    class="dr-btn dr-btn--primary"
                    :disabled="isRunning || isAwaiting || customerQuery.trim().length === 0"
                    @click="ask"
                  >
                    {{ isRunning ? 'Running…' : 'Send' }}
                  </button>
                  <button
                    v-if="isRunning && !isAwaiting"
                    type="button"
                    class="dr-btn dr-btn--cancel"
                    @click="cancel"
                  >
                    Cancel
                  </button>
                  <button
                    v-if="conversation.length > 0 && !isRunning"
                    type="button"
                    class="dr-btn dr-btn--ghost"
                    @click="reset"
                  >
                    Reset
                  </button>
                </div>
              </div>
            </div>
          </template>

          <!-- Operator tab -->
          <template #operator>
            <div class="dr-operator-pane">
              <template v-if="isAwaiting">
                <div class="dr-operator-alert">
                  <span class="dr-operator-alert-icon">!</span>
                  <span class="dr-operator-alert-text">Customer request requires operator response</span>
                </div>
                <div v-if="escalationReason.length > 0" class="dr-operator-reason">
                  <span class="dr-operator-reason-label">Reason:</span>
                  {{ escalationReason }}
                </div>
                <div v-if="conversation.length > 0" class="dr-operator-last-msg">
                  <span class="dr-operator-msg-label">Customer said:</span>
                  <blockquote class="dr-operator-msg-quote">
                    {{ conversation[conversation.length - 1]?.text ?? '' }}
                  </blockquote>
                </div>
                <textarea
                  v-model="operatorInput"
                  class="dr-textarea dr-operator-textarea"
                  rows="4"
                  placeholder="Type operator response here…"
                />
                <button
                  type="button"
                  class="dr-btn dr-btn--primary"
                  :disabled="operatorInput.trim().length === 0 || isRunning"
                  @click="sendOperatorResponse"
                >
                  {{ isRunning ? 'Resuming…' : 'Send response' }}
                </button>
              </template>
              <template v-else>
                <div class="dr-operator-idle">
                  <p class="dr-operator-idle-text">
                    AI handling — no operator action needed.
                  </p>
                  <p class="dr-operator-idle-sub" v-if="conversation.length === 0">
                    Send a customer message to watch the classifier route it.
                  </p>
                  <p class="dr-operator-idle-sub" v-else>
                    Try an escalation keyword ("refund", "billing") or flip the trolley switch to HUMAN GATE.
                  </p>
                </div>
              </template>
            </div>
          </template>

        </PanesTabs>
      </template>

      <!-- RIGHT: DAG | Config | Trace -->
      <template #right>
        <PanesTabs
          :tabs="rightTabs"
          default-key="dag"
          class="dr-tabs dr-tabs--right"
        >

          <!-- DAG tab: live execution graph -->
          <template #dag>
            <div class="dr-graph-pane">
              <DagGraph
                ref="dagGraph"
                :dag="dispatcherDag"
                :node-variants="DISPATCHER_NODE_VARIANTS"
                :expand-all="false"
                aria-label="Dispatcher DAG live execution"
              />
            </div>
          </template>

          <!-- Config tab: trolley switch + example prompts -->
          <template #config>
            <div class="dr-config-pane">

              <!-- Trolley switch -->
              <section class="dr-config-section">
                <h5 class="dr-config-head">Routing mode</h5>
                <label class="dr-trolley">
                  <span :class="['dr-trolley-label', !humanMode ? 'dr-trolley-label--active' : '']">AI AUTO</span>
                  <button
                    type="button"
                    :class="['dr-trolley-track', humanMode ? 'dr-trolley-track--human' : '']"
                    :aria-pressed="humanMode"
                    aria-label="Toggle routing mode"
                    @click="humanMode = !humanMode"
                  >
                    <span class="dr-trolley-thumb" />
                  </button>
                  <span :class="['dr-trolley-label', humanMode ? 'dr-trolley-label--active dr-trolley-label--warn' : '']">HUMAN GATE</span>
                </label>
                <p class="dr-config-hint" v-if="humanMode">
                  All messages will route to the operator regardless of content.
                </p>
                <p class="dr-config-hint" v-else>
                  The classifier routes routine queries to AI; escalation keywords force the operator.
                </p>
              </section>

              <!-- Classification mode switch -->
              <section class="dr-config-section">
                <h5 class="dr-config-head">Classification mode</h5>
                <label class="dr-trolley">
                  <span :class="['dr-trolley-label', classificationMode === 'embedder' ? 'dr-trolley-label--active' : '']">EMBEDDER</span>
                  <button
                    type="button"
                    :class="['dr-trolley-track', classificationMode === 'llm' ? 'dr-trolley-track--human' : '']"
                    :aria-pressed="classificationMode === 'llm'"
                    aria-label="Toggle classification mode"
                    @click="classificationMode = classificationMode === 'embedder' ? 'llm' : 'embedder'"
                  >
                    <span class="dr-trolley-thumb" />
                  </button>
                  <span :class="['dr-trolley-label', classificationMode === 'llm' ? 'dr-trolley-label--active' : '']">LLM</span>
                </label>
                <p class="dr-config-hint" v-if="classificationMode === 'embedder'">
                  On-device cosine-similarity triage against three intent anchors — instant,
                  no LLM round-trip after the embedder loads once.
                </p>
                <p class="dr-config-hint" v-else>
                  Generative classification via the LLM adapter — slower, since every message
                  loads/queries the model.
                </p>
                <p class="dr-status-line">
                  {{ embedderDisplayName ?? 'embedder provisions on first execution' }}
                  · mode: {{ classificationMode }}
                </p>
              </section>

              <!-- Example prompts -->
              <section class="dr-config-section">
                <h5 class="dr-config-head">Example prompts</h5>
                <ul class="dr-prompt-list">
                  <li v-for="prompt in EXAMPLE_PROMPTS" :key="prompt">
                    <button
                      type="button"
                      class="dr-prompt-btn"
                      :disabled="isRunning || isAwaiting"
                      @click="fillPrompt(prompt)"
                    >{{ prompt }}</button>
                  </li>
                </ul>
              </section>

              <!-- Escalation reason -->
              <section v-if="escalationReason.length > 0" class="dr-config-section">
                <h5 class="dr-config-head">Last escalation reason</h5>
                <p class="dr-escalation-reason">{{ escalationReason }}</p>
              </section>

            </div>
          </template>

          <template #llm>
            <div class="dr-config-pane">
              <LlmConfigurationPane
                :backends="backends"
                :active-id="activeBackend"
                :api-keys="apiKeys"
                :preferred-models="preferredModels"
                :is-mobile="isMobile"
                :disabled="isRunning"
                @update:active-id="selectBackend"
                @update:api-keys="apiKeys = $event"
                @update:preferred-models="selectPreferredModels"
              />
            </div>
          </template>

          <!-- Trace tab -->
          <template #trace>
            <TraceFeed
              :entries="trace"
              :log-events="logEvents"
            />
          </template>

        </PanesTabs>
      </template>
    </RunnableExampleWorkbench>
    </template>
  </div>
</template>

