// ── State ────────────────────────────────────────────────────────────────────
const isRunning = ref(false);
const isDone = ref(false);
const errorMessage = ref<string | null>(null);
const trace = ref<TraceEvent[]>([]);

/** Live streaming feed: one entry per gathered EnrichedShipment record. */
