  const jlist = [...journeysMap.value.values()].filter((j) => j.scanCount >= 2);
  jlist.sort((a, b) => b.scanCount - a.scanCount);
  return jlist.slice(0, 3);
});

/** Captured-error groups ranked by count, from the bounded error rollup. */
const errorGroups = computed<ErrorGroupType[]>(() => ErrorRollup.ranked(errorRollupState.value));

/** Flow-state hint displayed in the left column header. */
const flowHint = computed<string>(() => {
  if (isRunning.value) {
    return progressPct.value > 0
      ? `streaming ${String(progressPct.value)}%`
      : 'streaming…';
  }
  if (isDone.value) return `${processedCount.value.toLocaleString()} events processed`;
  return 'ready';
});

const averageFlushMs = computed<number>(() => {
  const flushCount = mainThreadStats.value.flushCount;
  if (flushCount === 0) return 0;
  return mainThreadStats.value.totalFlushMs / flushCount;
});

const telemetrySnapshot = computed<CartographerBrowserTelemetryType>(() =>
  buildCartographerBrowserTelemetry({
    'status': errorMessage.value !== null
      ? 'failed'
      : isRunning.value
        ? 'running'
        : isDone.value
          ? 'completed'
          : 'idle',
    'progressPct': mainThreadStats.value.flushCount === 0 && !isRunning.value && !isDone.value
      ? 0
      : progressPct.value,
    'processedCount': processedCount.value,
    'totalEvents': totalEvents,
    'sampleRecordCount': records.value.length,
    'insightCount': insightsMap.value.size,
    'journeyCount': journeysMap.value.size,
    'errorMessage': errorMessage.value,
    'flushCount': mainThreadStats.value.flushCount,
    'averageFlushMs': averageFlushMs.value,
    'lastFlushMs': mainThreadStats.value.lastFlushMs,
    'maxFlushMs': mainThreadStats.value.maxFlushMs,
    'stateRefreshCount': mainThreadStats.value.stateRefreshCount,
    'skippedStateRefreshCount': mainThreadStats.value.skippedStateRefreshCount,
    'graphMutationCount': mainThreadStats.value.graphMutationCount,
  }),
);

const telemetryJson = computed<string>(() => JSON.stringify(telemetrySnapshot.value));

// ── Tabs ─────────────────────────────────────────────────────────────────────
const leftTabs = computed(() => [
  {
    'key': 'stream',
    'label': 'Stream',
    'badge': isRunning.value ? 'live' : (processedCount.value > 0 ? String(processedCount.value) : ''),
    'tone': (isRunning.value ? 'live' : 'default') as 'live' | 'default',
  },
  {
    'key': 'insights',
    'label': 'Insights',
    'badge': isDone.value && continentRows.value.length > 0 ? String(continentRows.value.length) : '',
    'tone': 'accent' as const,
  },
  {
    'key': 'compare',
    'label': 'Compare',
    'badge': isDone.value ? String(records.value.length) : '',
    'tone': 'accent' as const,
  },
]);

const rightTabs = computed(() => [
  {
    'key': 'dag',
    'label': 'DAG Topology',
    'badge': isRunning.value ? 'live' : '',
    'tone': (isRunning.value ? 'live' : 'default') as 'live' | 'default',
  },
  {
    'key': 'config',
    'label': 'Configuration',
    'badge': String(clampedTotal.value),
    'tone': 'default' as const,
  },
  {
    'key': 'trace',
    'label': 'Trace',
    'badge': String(trace.value.length > 0 ? trace.value.length : ''),
    'tone': (isRunning.value ? 'live' : 'default') as 'live' | 'default',
  },
]);

// ── Helpers ──────────────────────────────────────────────────────────────────

function usdFromMinor(minor: number): string {
  return `$${(minor / 100).toFixed(2)}`;
}

function pct(part: number, total: number): string {
  if (total === 0) return '0%';
  return `${Math.round((part / total) * 100)}%`;
}

/** Scroll the stream feed to the bottom so newest entries are visible. */
function scrollFeedToBottom(): void {
  if (feedContainerRef.value !== null) {
    feedContainerRef.value.scrollTop = feedContainerRef.value.scrollHeight;
  }
}

function publishTelemetry(): void {
  if (typeof window === 'undefined') return;
  (window as BrowserWindowWithCartographerTelemetry)[CARTOGRAPHER_BROWSER_TELEMETRY_KEY] = telemetrySnapshot.value;
}

// ── Browser observer (class extension) ───────────────────────────────────────
// CartographerBrowserObserver subclasses ObservedDag<CartographerState> to add
// Vue-reactive DOM updates on top of the base leveled logging. The buffered
// cadence below decouples DOM mutation frequency from event throughput and the
// component's presentation cadence.
const _cartographerLogger = new ConsoleLogger();

class CartographerBrowserObserver extends ObservedDag<CartographerState> {
  protected override onNodeStart(
    nodeName: string,
    state: CartographerState,
    placementPath: readonly string[],
    signal: AbortSignal,
  ): void {
    // Base ObservedDag logging (timing + structured LogBody + logger.debug) is
    // skipped for inner nodes: a streaming scatter fires this hook once per
    // event × sub-DAG node, and the base work is O(1) allocation + a log call
    // per firing. Top-level nodes keep full logging/timing/trace behavior;
    // inner-node animation still runs via the bounded presentation sets below.
    if (placementPath.length === 0) {
      super.onNodeStart(nodeName, state, placementPath, signal);
    }
    const fullId = [...placementPath, nodeName].join('/');
    frameActiveNodes.add(fullId);
    // Trace records top-level node events only; inner per-clone activity is
    // conveyed through the progress bar, feed, and throttled graph lighting.
    if (placementPath.length === 0) {
      pushTrace({ 'variant': 'start', 'node': fullId, 'ts': Date.now() });
    }
    scheduleFlush();
  }

  protected override onNodeEnd(
    nodeName: string,
    output: string | null,
    state: CartographerState,
    placementPath: readonly string[],
    signal: AbortSignal,
  ): void {
    // See onNodeStart: base logging/timing is skipped for inner nodes.
    if (placementPath.length === 0) {
      super.onNodeEnd(nodeName, output, state, placementPath, signal);
    }
    const fullId = [...placementPath, nodeName].join('/');
    latestRunState = state;
    frameActiveNodes.delete(fullId);
    frameCompletedNodes.add(fullId);
    if (output !== null) frameTraversedEdges.add(`${fullId}|${output}`);
    if (placementPath.length === 0) {
      pushTrace({ 'variant': 'end', 'node': fullId, 'ts': Date.now(), output });
    }
    scheduleFlush();
  }

  protected override onError(
    nodeName: string,
    error: Error,
    state: CartographerState,
    placementPath: readonly string[],
    signal: AbortSignal,
  ): void {
    // See onNodeStart: base logging/timing is skipped for inner nodes.
    if (placementPath.length === 0) {
      super.onError(nodeName, error, state, placementPath, signal);
    }
    const fullId = [...placementPath, nodeName].join('/');
    frameErroredNode = fullId;
    pushTrace({ 'variant': 'error', 'node': fullId, 'ts': Date.now(), 'message': error.message !== '' ? error.message : String(error) });
    scheduleFlush();
  }

  protected override onFlowEnd(
    dagName: string,
    state: CartographerState,
    result: import('@studnicky/dagonizer').ExecutionResultType<CartographerState>,
    signal: AbortSignal,
  ): void {
    super.onFlowEnd(dagName, state, result, signal);
    if (flushHandle !== 0) window.clearTimeout(flushHandle);
    flushHandle = 0;
    flushScheduled = false;
    latestRunState = state;
    flushLiveState(state);
  }
}

// ── Live-update throttling (survives 1,000,000-event runs) ───────────────────
// The streaming scatter fires onNodeStart/onNodeEnd for every inner node of
// every clone — N events × M sub-DAG nodes is millions of observer calls.
// Mutating a reactive ref on each call is O(n²) and freezes the tab. The
// observer instead writes plain buffers and schedules a single
// timed flush, so the DOM updates at a stable human-visible cadence regardless
// of event throughput. Node-id and edge sets are bounded by the static sub-DAG
// (~dozens), never by event count.
const MAX_TRACE = 60;
let latestRunState: CartographerState | null = null;
let traceBuffer: TraceEvent[] = [];
const frameActiveNodes = new Set<string>();
const frameCompletedNodes = new Set<string>();
const frameTraversedEdges = new Set<string>();
let frameErroredNode: string | null = null;
let flushScheduled = false;
let flushHandle = 0;
let lastRenderedProcessed = -1;
let presentationFlush: Promise<void> = Promise.resolve();

function pushTrace(entry: TraceEvent): void {
  traceBuffer.push(entry);
  if (traceBuffer.length > MAX_TRACE) {
    traceBuffer = traceBuffer.slice(-MAX_TRACE);
  }
}

/** Exact processed-event count from the bounded region rollup. */
/** Push progress, feed, and processed-count from a state snapshot. */
function applyLiveState(state: CartographerState, force: boolean = false): boolean {
  const presentation = CartographerPresentation.of(state);
  const processed = presentation.processedCountExact;
  if (!force && processed === lastRenderedProcessed) return false;
  lastRenderedProcessed = processed;
  processedCount.value = processed;
  if (totalEvents > 0) {
    progressPct.value = Math.min(100, Math.round((processed / totalEvents) * 100));
  }
  streamFeed.value = [...buildLiveStreamFeed(
    presentation.sampleRecords,
    presentation.sampleRecordsCursor,
    presentation.sampleRecordsWrapped,
    MAX_VISIBLE_FEED,
  )];
  return true;
}

/** Apply buffered observer state through one serialized presentation queue. */
function flushLiveState(finalState: CartographerState | null = null): Promise<void> {
  presentationFlush = presentationFlush.then(async () => {
    const startedAt = performance.now();
    const graphMutations =
      frameCompletedNodes.size
      + frameActiveNodes.size
      + frameTraversedEdges.size
      + (frameErroredNode === null ? 0 : 1);
    for (const id of frameCompletedNodes) dagGraph.value?.setCompleted(id);
    frameCompletedNodes.clear();
    for (const id of frameActiveNodes) dagGraph.value?.setActive(id);
    frameActiveNodes.clear();
    for (const edge of frameTraversedEdges) {
      const sep = edge.lastIndexOf('|');
      dagGraph.value?.markEdgeTraversed(edge.slice(0, sep), edge.slice(sep + 1));
    }
    frameTraversedEdges.clear();
    if (frameErroredNode !== null) { dagGraph.value?.setErrored(frameErroredNode); frameErroredNode = null; }

    trace.value = traceBuffer.slice(-MAX_TRACE);
    const state = finalState ?? latestRunState;
    const stateRefreshed = state === null ? false : applyLiveState(state, finalState !== null);
    if (finalState !== null) {
      const finalPresentation = CartographerPresentation.of(finalState);
      records.value = [...finalPresentation.sampleRecords];
      insightsMap.value = new Map(finalPresentation.insights);
      journeysMap.value = new Map(finalPresentation.journeys);
      errorRollupState.value = finalPresentation.errorRollup;
      progressPct.value = 100;
    }

    await nextTick();

    const elapsedMs = performance.now() - startedAt;
    const stats = mainThreadStats.value;
    stats.flushCount++;
    stats.graphMutationCount += graphMutations;
    stats.lastFlushMs = elapsedMs;
    stats.totalFlushMs += elapsedMs;
    if (elapsedMs > stats.maxFlushMs) stats.maxFlushMs = elapsedMs;
    if (stateRefreshed) stats.stateRefreshCount++;
    else stats.skippedStateRefreshCount++;
    if (stateRefreshed) scrollFeedToBottom();
    publishTelemetry();
  });
  return presentationFlush;
}

function runScheduledFlush(): void {
  flushHandle = 0;
  flushScheduled = false;
  flushLiveState();
}

function scheduleFlush(): void {
  if (flushScheduled) return;
  flushScheduled = true;
  flushHandle = window.setTimeout(runScheduledFlush, clampedLiveFlushMs.value);
}

/** Reset throttle buffers between runs. */
function resetLiveBuffers(): void {
  if (flushHandle !== 0) window.clearTimeout(flushHandle);
  flushHandle = 0;
  flushScheduled = false;
  latestRunState = null;
  traceBuffer = [];
  lastRenderedProcessed = -1;
  frameActiveNodes.clear();
  frameCompletedNodes.clear();
  frameTraversedEdges.clear();
  frameErroredNode = null;
  presentationFlush = Promise.resolve();
  errorRollupState.value = ErrorRollup.empty();
  mainThreadStats.value = {
    'flushCount': 0,
    'stateRefreshCount': 0,
    'skippedStateRefreshCount': 0,
    'graphMutationCount': 0,
    'lastFlushMs': 0,
    'maxFlushMs': 0,
    'totalFlushMs': 0,
  };
  publishTelemetry();
}

// ── Run ───────────────────────────────────────────────────────────────────────
async function run(): Promise<void> {
  if (isRunning.value) return;

  isRunning.value = true;
  isDone.value = false;
  errorMessage.value = null;
  trace.value = [];
  records.value = [];
  insightsMap.value = new Map();
  journeysMap.value = new Map();
  streamFeed.value = [];
  processedCount.value = 0;
  progressPct.value = 0;
  totalEvents = clampedTotal.value;
  resetLiveBuffers();
  publishTelemetry();

  await dagGraph.value?.reset();

  let dispatcher: CartographerBrowserObserver | null = null;

  try {
    // Offline recorded geo on both sides: the worker registry builds its own
    // recorded services record; the main thread (seed + summarize + gather) needs
    // no network. Deterministic and infeasible-to-network-at-1M.
    GeoResolvers.recorded();

    // #region cartographer-browser-containers
    // Separate role bindings use the same worker entry and registry while still
    // keeping the DAG's execution boundaries explicit: process-stream runs on
    // `cpu`, summarize-insights runs on `io`.
    const cpuContainer = new CartographerWorkerContainer({
      'registryModule':  new URL('./cartographerWorkerEntry.ts', import.meta.url).href,
      'registryVersion': '1.0.0',
      'servicesConfig':  { 'useRecordedIp': true },
      'poolSize':        clampedPoolSize.value,
      'instrumentationPlacementPathDepth': 1,
    });
    const ioContainer = new CartographerWorkerContainer({
      'registryModule':  new URL('./cartographerWorkerEntry.ts', import.meta.url).href,
      'registryVersion': '1.0.0',
      'servicesConfig':  { 'useRecordedIp': true },
      'poolSize':        1,
      'instrumentationPlacementPathDepth': 1,
    });

    dispatcher = new CartographerBrowserObserver(_cartographerLogger, {
      'executionTopologyStore': new DiscardingGraphDataset(),
      'containers': {
        'cpu': cpuContainer,
        'io':  ioContainer,
      },
    });
    // #endregion cartographer-browser-containers

    dispatcher.registerBundle(CartographerBrowserRuntime.bundle({
      'execution': {
        'batching': {
          'mode': 'reservoir',
          'concurrency': clampedPoolSize.value,
          'reservoir': {
            'keyField': 'eventType',
            'capacity': clampedBatchCapacity.value,
            'idleMs': clampedReservoirIdleMs.value === 0 ? null : clampedReservoirIdleMs.value,
          },
        },
      },
    }));

    const state = new CartographerState();

    // Apportion the total across payload types by share. Streaming is the only
    // execution mode — the generative streamer yields events lazily so memory
    // stays flat regardless of total.
    const counts = derivedCounts.value;
    state.eventConfig = typeRows.value.map((r, i) => ({
      'eventType':  r.eventType,
      'count':      counts[i] ?? 0,
      'formatMix':  DEFAULT_FORMAT_MIX,
    }));

    state.useStreamingSource = true;
    state.streamCount = clampedTotal.value;
    state.eventCount = clampedTotal.value;

    activeAbortController = new AbortController();

    // #region cartographer-streaming-execution
    // The observer hooks already drive progress, feed, trace, and graph
    // updates. Await the execution summary directly so the browser does not
    // also drain every stage on the main thread during million-event runs.
    await dispatcher.execute(CARTOGRAPHER_IRIS.dag.cartographer, state, {
      'signal': activeAbortController.signal,
    });
    await presentationFlush;
    // #endregion cartographer-streaming-execution
  } catch (error) {
    errorMessage.value = error instanceof Error ? error.message : String(error);
    publishTelemetry();
  } finally {
    await dispatcher?.destroy();
    activeAbortController = null;
    isRunning.value = false;
    isDone.value = true;
    publishTelemetry();
  }
}

function reset(): void {
  if (isRunning.value) return;
  records.value = [];
  insightsMap.value = new Map();
  journeysMap.value = new Map();
  trace.value = [];
  streamFeed.value = [];
  processedCount.value = 0;
  progressPct.value = 0;
  totalEvents = 0;
  resetLiveBuffers();
  isDone.value = false;
  errorMessage.value = null;
  publishTelemetry();
  void dagGraph.value?.reset();
}

// ── Boot ──────────────────────────────────────────────────────────────────────
// SSR guard: browser-only initialisation goes here.
onMounted(() => {
  // No auto-run: the visitor clicks Run to start.
  void (async () => {
    await primeTopLevelDag();
    const harness = parseCartographerBrowserHarness(window.location.search);
    if (harness.totalEvents !== null) totalEventsInput.value = harness.totalEvents;
    if (harness.poolSize !== null) poolSizeInput.value = harness.poolSize;
    if (harness.batchCapacity !== null) batchCapacityInput.value = harness.batchCapacity;
    if (harness.reservoirIdleMs !== null) reservoirIdleMsInput.value = harness.reservoirIdleMs;
    if (harness.liveFlushMs !== null) liveFlushMsInput.value = harness.liveFlushMs;
    publishTelemetry();
    if (harness.loadEmbeddedTopology) await loadEmbeddedTopology();
    if (harness.autorun) await nextTick(run);
  })();
});
</script>

<template>
