#### `CartographerServices`

The dependency record passed into node constructors. Services carry two
transport adapters: `ipGeolocator` (live `freeipapi.com` or committed fixture
replay) and `addressGeocoder` (live OpenStreetMap Nominatim or deterministic
no-answer in the smoke). Coords, locale, code, and phone resolution are fully
offline — `GeohashTzMap`, `CoordTimezone`, and `CallingCode` need no injected
transport.

```ts
export interface CartographerServices {
  /** IP-modality transport (geolocate gateway IP → place). */
  readonly ipGeolocator: IpGeolocator;
  /** Address-modality transport (forward-geocode postal address → place). */
  readonly addressGeocoder: AddressGeocoder;
}
```

#### `GeoResolvers`

Factory that assembles the `CartographerServices` record for the chosen backend.

```ts
export class GeoResolvers {
  /** Live services: live freeipapi IP geolocation and Nominatim address geocoding. */
  static live(): CartographerServices {
    return {
      'ipGeolocator':    new LiveIpGeolocator(),
      'addressGeocoder': new LiveAddressGeocoder(),
    };
  }

  /** Recorded services: fixture-replay IP geolocation and deterministic address geocoding.
   *  Deterministic and offline — used by the smoke and `--recorded` CLI flag. */
  static recorded(): CartographerServices {
    return {
      'ipGeolocator':    new RecordedIpGeolocator(),
      'addressGeocoder': new RecordedAddressGeocoder(),
    };
  }
}
```

### Key nodes

#### `producerFeeds` and `SourceIntakeGather` — producer DAG fan-in

Each data-type entrypoint targets its own producer stream-feed DAG. That DAG
opens the producer-local source stream, scatters each source payload through
`ingest-source` for decompress/parse/normalize/validate, and returns source
payload batches to the top-level `intake-gather` placement. The `source-intake`
gather is the open fan-in that merges those producer DAG outputs into the
single shared `source-payload` collection the enrichment scatter reads.

```ts
class ProducerFeedNode extends MonadicNode<CartographerState, 'ready' | 'empty'> {
  readonly '@id': string;
  readonly 'name': string;
  readonly 'outputs' = ['ready', 'empty'] as const;

  readonly #eventType: SourcePayload['eventType'];

  constructor(eventType: SourcePayload['eventType']) {
    super();
    this.#eventType = eventType;
    this['@id'] = `urn:noocodec:node:cartographer-feed-${eventType}`;
    this.name = `feed-${eventType}`;
  }

  override get outputSchema(): Record<'ready' | 'empty', SchemaObjectType> {
    return {
      'ready': { 'type': 'object' },
      'empty': { 'type': 'object' },
    };
  }

  override async execute(
    batch: Batch<CartographerState>,
    _context: NodeContextType,
  ): Promise<RoutedBatchType<'ready' | 'empty', CartographerState>> {
    const ready: ItemType<CartographerState>[] = [];
    const empty: ItemType<CartographerState>[] = [];

    for (const item of batch) {
      const totalCount = item.state.streamCount > 0 ? item.state.streamCount : undefined;
      item.state.sourceFeed = EventStreamSource.streamProducer(item.state.eventConfig, this.#eventType, totalCount);
      if (EventStreamSource.hasProducer(item.state.eventConfig, this.#eventType, totalCount)) {
        ready.push(item);
      } else {
        empty.push(item);
      }
    }

    const routed = new Map<'ready' | 'empty', Batch<CartographerState>>();
    if (ready.length > 0) routed.set('ready', Batch.from(ready));
    if (empty.length > 0) routed.set('empty', Batch.from(empty));
    return routed;
  }
}

export const feedPositionPing = new ProducerFeedNode('position-ping');
export const feedFacilityScan = new ProducerFeedNode('facility-scan');
export const feedSensorReading = new ProducerFeedNode('sensor-reading');
export const feedCustomsEvent = new ProducerFeedNode('customs-event');
export const feedDeliveryConfirmation = new ProducerFeedNode('delivery-confirmation');

export const producerFeedNodes = [
  feedPositionPing,
  feedFacilityScan,
  feedSensorReading,
  feedCustomsEvent,
  feedDeliveryConfirmation,
] as const;
```

```ts
import type { CartographerState } from '../CartographerState.ts';
import { CARTOGRAPHER_IRIS } from '../cartographerIds.ts';
import {
  feedPositionPing,
  feedFacilityScan,
  feedSensorReading,
  feedCustomsEvent,
  feedDeliveryConfirmation,
  producerFeedNodes,
} from '../nodes/producerFeeds.ts';

import type { DAGType, DispatcherBundleType, NodeInterface } from '@studnicky/dagonizer';
import { DAGBuilder } from '@studnicky/dagonizer';

type ProducerFeedSpecType = {
  readonly eventType: typeof CARTOGRAPHER_IRIS.intakeEventTypes[number];
  readonly feedNode: NodeInterface<CartographerState, 'ready' | 'empty'>;
};

const PRODUCER_FEED_SPECS: readonly ProducerFeedSpecType[] = [
  { 'eventType': 'position-ping',         'feedNode': feedPositionPing },
  { 'eventType': 'facility-scan',         'feedNode': feedFacilityScan },
  { 'eventType': 'sensor-reading',        'feedNode': feedSensorReading },
  { 'eventType': 'customs-event',         'feedNode': feedCustomsEvent },
  { 'eventType': 'delivery-confirmation', 'feedNode': feedDeliveryConfirmation },
];

class ProducerFeedDAGBuilder {
  private constructor() { /* static-only */ }

  static build(spec: ProducerFeedSpecType): DAGType {
    const dagIri = CARTOGRAPHER_IRIS.streamFeedDagIri(spec.eventType);
    const placement = (id: string): string => CARTOGRAPHER_IRIS.placementIri(dagIri, id);

    return new DAGBuilder(dagIri, '1.0')
      .node(placement(`feed-${spec.eventType}`), spec.feedNode, {
        'ready': placement('done'),
        'empty': placement('done'),
      })
      .terminal(placement('done'), { outcome: 'completed' })
      .build();
  }
}

export const streamProducerFeedDAGs: DAGType[] = PRODUCER_FEED_SPECS.map((spec) =>
  ProducerFeedDAGBuilder.build(spec),
);

export const streamProducerFeedBundle: DispatcherBundleType<CartographerState> = {
  'nodes': [...producerFeedNodes],
  'dags': streamProducerFeedDAGs,
};
```

```ts
export class SourceIntakeGather extends GatherStrategy {
  readonly name = 'source-intake';
  readonly '@id' = 'urn:noocodec:node:source-intake';

  // `record.result` for this gather is `state.sourceFeed`: a live
  // `AsyncIterable<SourcePayload>` handle (see
  // `CartographerSourceIntake.mergeRecords`/`requireRecordFeed`), not
  // JSON-serialisable data. Compacting it into a durable `GatherRecordProgress`
  // (a JSON checkpoint payload) cannot survive a serialize/restore round trip —
  // there is no way to reconstruct a live async generator from its JSON
  // projection. `mode: 'full'` is the honest declaration: this gather cannot
  // participate in result-only durable replay, regardless of how narrow its
  // in-process clone-state read is.
  override transientResultSelection(): TransientNodeStateSelectionType {
    return { 'mode': 'full', 'domainPaths': [], 'metadataKeys': [] };
  }

  override initial(
    _config: GatherConfigType,
    state: NodeStateInterface,
    accessor: StateAccessorInterface,
  ): void {
    accessor.set(state, 'source-payload', []);
  }

  override reduce(
    _config: GatherConfigType,
    batch: Parameters<GatherStrategy['reduce']>[1],
    state: NodeStateInterface,
    accessor: StateAccessorInterface,
  ): void {
    const records: GatherRecordType[] = [];
    for (const item of batch) records.push(item.state);
    const mergedPayload = CartographerSourceIntake.mergeRecords(records);
    accessor.set(state, 'source-payload', mergedPayload);
  }
}

GatherStrategies.register(new SourceIntakeGather());
```

#### `canonicalizeCore` — timestamp and location normalization

After geo-enrichment sets `state.geoContext.timezone`, `canonicalizeCore` converts the
raw timestamp to a UTC epoch, then derives the local time at the scan's IANA timezone
using `Intl.DateTimeFormat`. Cross-zone journeys show different local times and UTC
offsets per scan.

```ts
export class CanonicalizeCoreNode extends MonadicNode<CartographerState, 'normalized' | 'rejected'> {
  readonly '@id' = 'urn:noocodec:node:canonicalize-core';
  readonly 'name' = 'canonicalize-core';
  readonly 'outputs' = ['normalized', 'rejected'] as const;

  override get outputSchema(): Record<'normalized' | 'rejected', SchemaObjectType> {
    return {
      'normalized': { 'type': 'object' },
      'rejected':   { 'type': 'object' },
    };
  }

  override async execute(
    batch: Batch<CartographerState>,
    _context: NodeContextType,
  ): Promise<RoutedBatchType<'normalized' | 'rejected', CartographerState>> {
    const acc = new Map<'normalized' | 'rejected', ItemType<CartographerState>[]>();

    for (const item of batch) {
      const result = this.routeItem(item.state);
      for (const error of result.errors) {
        item.state.collectError(error);
      }
      const bucket = acc.get(result.output);
      if (bucket === undefined) {
        acc.set(result.output, [item]);
      } else {
        bucket.push(item);
      }
    }

    const routed = new Map<'normalized' | 'rejected', Batch<CartographerState>>();
    for (const [output, items] of acc) {
      routed.set(output, Batch.from(items));
    }
    return routed;
  }

  private routeItem(state: CartographerState): NodeOutputType<'normalized' | 'rejected'> {
    const raw = state.raw;

    const epochMs = TimeNormalizer.toEpochMs(raw.rawTimestamp);
    if (!isFinite(epochMs) || epochMs <= 0) {
      return NodeOutput.create('rejected');
    }

    const dispatchEpochMs = TimeNormalizer.toEpochMs(raw.rawDispatchAt);
    const validDispatch = isFinite(dispatchEpochMs) && dispatchEpochMs > 0 ? dispatchEpochMs : epochMs;

    const promisedEpochMs = TimeNormalizer.toEpochMs(raw.rawPromisedDeliveryAt);
    const validPromised = isFinite(promisedEpochMs) && promisedEpochMs > 0 ? promisedEpochMs : validDispatch + 7 * 86_400_000;

    const { localIso, utcOffset } = TimeZoneResolver.localParts(epochMs, state.geoContext.timezone);

    const { carrierId, carrierName } = CarrierRegistry.canonical(raw.carrier);
    const countryIso3 = CountryCodes.toIso3(raw.recipientCountry);
    const disruptionHours = Disruptions.hoursFor(raw.disruptionReason);

    // Derive classification at weightGrams=0. canonicalizeFacility will override
    // weightGrams/serviceTier/sizeTier with the real weight for facility-scan events.
    const status      = EventClassifier.eventType(raw.rawStatus);
    const serviceTier = EventClassifier.serviceTier(carrierId, 0);
    const sizeTier    = EventClassifier.sizeTier(0);

    state.normalized = {
      'shipmentId':       raw.shipmentId,
      'scanSeq':          raw.scanSeq,
      'epochMs':          epochMs,
      'dispatchEpochMs':  validDispatch,
      'isoTimestamp':     TimeNormalizer.toIso(epochMs),
      'localIso':         localIso,
      'utcOffset':        utcOffset,
      'carrierId':        carrierId,
      'carrierName':      carrierName,
      'countryIso3':      countryIso3,
      'weightGrams':      0,
      'status':           status,
      'serviceTier':      serviceTier,
      'sizeTier':         sizeTier,
      'lineItems':        [{ 'productId': '', 'quantity': 1 }],
      'facilityId':       '',
      'latitude':         raw.latitude,
      'longitude':        raw.longitude,
      'legFromLat':       raw.legFromLat,
      'legFromLng':       raw.legFromLng,
      'originLat':        raw.originLat,
      'originLng':        raw.originLng,
      'destLat':          raw.destLat,
      'destLng':          raw.destLng,
      'recipientName':    '',
      'recipientEmail':   '',
      'recipientPhone':   '',
      'recipientAddress': '',
      'recipientCountry': raw.recipientCountry,
      'marketingConsent': false,
      'promisedEpochMs':  validPromised,
      'disruptionHours':  disruptionHours,
      'disruptionReason': raw.disruptionReason,
    };

    return NodeOutput.create('normalized');
  }
}

export const canonicalizeCore = new CanonicalizeCoreNode();
