      '@id': 'urn:noocodec:dag:chat/node/respond',
      '@type':  'SingleNode',
      "name":     'respond',
      "node":     'urn:noocodec:node:respond',
      "outputs":  { "success": 'urn:noocodec:dag:chat/node/end' },               // routes to canonical terminal
    },
