### Interface: `RemoteStoreInterface`

`@studnicky/dagonizer/contracts`

Extension of `StoreInterface` for distributed or network-backed implementations.
Plugins that talk over HTTP, gRPC, or WebSocket, or that replicate state
across processes, implement `RemoteStoreInterface` rather than `StoreInterface` directly.
Single-process and single-node-durable stores implement `StoreInterface` directly.

```ts twoslash
import type { RemoteStoreInterface, RemoteStoreEndpointType, RemoteStoreLeaseType } from '@studnicky/dagonizer/contracts';
```

```ts twoslash
import type { StoreInterface, RemoteStoreEndpointType, RemoteStoreLeaseType } from '@studnicky/dagonizer/contracts';
// ---cut---
interface RemoteStoreInterface extends StoreInterface {
  readonly endpoint: RemoteStoreEndpointType;
  acquireLease(subject: string, ttlMs: number, maxWaitMs: number): Promise<RemoteStoreLeaseType>;
  releaseLease(lease: RemoteStoreLeaseType): Promise<void>;
  health(timeoutMs: number): Promise<boolean>;
}
```

The engine consumes a `RemoteStoreInterface` through the `StoreInterface` contract. The extra
methods are observability and coordination primitives the dispatcher uses when
distributed execution is wired in.

#### Interface: `RemoteStoreEndpointType`

```ts twoslash
interface RemoteStoreEndpointType {
  readonly url:    string;
  readonly region: string;
}
```

| Field | Description |
|-------|-------------|
| `url` | Stable identifier for the remote endpoint (URL, gRPC target, etc.). |
| `region` | Region/zone hint for placement decisions. Default at construction: `''` (no region constraint). |

`region` is required. Implementations that have no region concept supply `''`.

#### Interface: `RemoteStoreLeaseType`

```ts twoslash
interface RemoteStoreLeaseType {
  readonly token:     string;
  readonly expiresAt: number;
  readonly subject:   string;
}
```

Opaque lease token returned by `acquireLease`. Applications treat `token` as
opaque; the store validates it on `releaseLease` and on writes when
leasing is enforced.

| Field | Description |
|-------|-------------|
| `token` | Opaque string the store recognises on `releaseLease` and write checks. |
| `expiresAt` | Monotonic ms timestamp the lease expires at (exclusive). |
| `subject` | Scope of the lease (e.g. a key namespace or DAG run id). |

#### Methods

| Method | Returns | Description |
|--------|---------|-------------|
| `endpoint` | `RemoteStoreEndpointType` | Endpoint descriptor; appears in observability output and placement decisions. |
| `acquireLease(subject, ttlMs, maxWaitMs)` | `Promise<RemoteStoreLeaseType>` | Acquire exclusive write authority for `subject` with a lifetime of `ttlMs` ms. Waits up to `maxWaitMs` for an active holder to release before throwing `StoreError(LEASE_DENIED)`. |
| `releaseLease(lease)` | `Promise<void>` | Release a previously-acquired lease. Idempotent: releasing an already-expired lease is a no-op. |
| `health(timeoutMs)` | `Promise<boolean>` | Health probe. Returns `true` when the endpoint is reachable and the backing responds within `timeoutMs`. Implementations must not throw on transport failure: return `false` so the dispatcher can route around an unhealthy store. |

#### Implementing `RemoteStoreInterface`

Extend `BaseStore` and implement the three additional methods plus the
`endpoint` property:

```ts
import { BaseStore } from '@studnicky/dagonizer/store';
import type { StoreSnapshotEntryType } from '@studnicky/dagonizer/store';
import type {
  RemoteStoreInterface,
  RemoteStoreEndpointType,
  RemoteStoreLeaseType,
} from '@studnicky/dagonizer';
import type { JsonValueType } from '@studnicky/dagonizer/entities';

/**
 * GrpcStore: stub RemoteStoreInterface backed by an in-memory map.
 * Network methods (connect, disconnect, health, acquireLease, releaseLease)
 * log instead of making real gRPC calls — illustrating the contract surface.
 */
export class GrpcStore extends BaseStore implements RemoteStoreInterface {
  readonly endpoint: RemoteStoreEndpointType;
  readonly #data = new Map<string, JsonValueType>();

  constructor(url: string, region: string = '') {
    super({ namespace: 'archivist' });
    this.endpoint = { url, region };
  }

  // ── RemoteStoreInterface distributed contract ─────────────────────────────────────

  override async connect(): Promise<void> {
    process.stdout.write(`[GrpcStore] connect -> ${this.endpoint.url}\n`);
  }

  override async disconnect(): Promise<void> {
    process.stdout.write(`[GrpcStore] disconnect -> ${this.endpoint.url}\n`);
  }

  async health(timeoutMs: number): Promise<boolean> {
    process.stdout.write(`[GrpcStore] health probe (timeout=${timeoutMs}ms)\n`);
    // Stub: always healthy in the example.
    return true;
  }

  async acquireLease(subject: string, ttlMs: number, maxWaitMs: number): Promise<RemoteStoreLeaseType> {
    process.stdout.write(`[GrpcStore] acquireLease subject=${subject} ttl=${ttlMs}ms maxWait=${maxWaitMs}ms\n`);
    return {
      token:     `token:${subject}:${Date.now()}`,
      expiresAt: Date.now() + ttlMs,
      subject,
    };
  }

  async releaseLease(lease: RemoteStoreLeaseType): Promise<void> {
    process.stdout.write(`[GrpcStore] releaseLease token=${lease.token}\n`);
  }

  // ── BaseStore abstract hooks ──────────────────────────────────────────────

  protected get snapshotType(): string    { return 'grpc-store'; }
  protected get snapshotVersion(): number { return 1; }

  protected async performGet(key: string): Promise<JsonValueType | null> {
    return this.#data.get(key) ?? null;
  }

  protected async performSet(key: string, value: JsonValueType): Promise<void> {
    this.#data.set(key, value);
  }

  protected async performHas(key: string): Promise<boolean> {
    return this.#data.has(key);
  }

  protected async performDelete(key: string): Promise<boolean> {
    return this.#data.delete(key);
  }

  protected async *performEntriesStream(): AsyncIterable<StoreSnapshotEntryType> {
    for (const [key, value] of this.#data.entries()) {
      yield { key, value };
    }
  }

  protected async performRestoreEntry(entry: StoreSnapshotEntryType): Promise<void> {
    this.#data.set(entry.key, entry.value);
  }

  protected async performClear(): Promise<void> {
    this.#data.clear();
  }

  // Override update for atomic RMW — in-memory direct access is safe.
  override async update(key: string, fn: (current: JsonValueType | undefined) => JsonValueType): Promise<JsonValueType> {
    const qualified = this.qualifyKey(key);
    const stored    = this.#data.get(qualified) ?? null;
    const current   = stored === null ? undefined : stored;
    const next      = fn(current);
    this.#data.set(qualified, next);
    return next;
  }
}
```

